DO $$ BEGIN CREATE TYPE "tournament_status" AS ENUM ('DRAFT', 'OPEN', 'ENTRY_CLOSED', 'TRADING_CLOSED', 'FINALIZING', 'COMPLETED', 'CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "display_name" varchar(120) NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "tournaments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "slug" varchar(120) NOT NULL, "name" varchar(200) NOT NULL, "description" text NOT NULL, "status" "tournament_status" NOT NULL DEFAULT 'DRAFT', "simulated_pool" numeric(20,2) NOT NULL CHECK (simulated_pool >= 0), "simulated_entry_contribution" numeric(20,2) NOT NULL CHECK (simulated_entry_contribution >= 0), "opens_at" timestamptz, "entry_closes_at" timestamptz, "trading_closes_at" timestamptz, "max_entries_per_user" integer NOT NULL CHECK (max_entries_per_user > 0), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "tournaments_slug_idx" ON "tournaments" ("slug");
CREATE TABLE IF NOT EXISTS "tournament_entries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tournament_id" uuid NOT NULL REFERENCES "tournaments"("id"), "user_id" uuid NOT NULL REFERENCES "users"("id"), "sequence_number" integer NOT NULL CHECK (sequence_number > 0), "starting_bankroll" numeric(20,2) NOT NULL CHECK (starting_bankroll >= 0), "cash" numeric(20,2) NOT NULL CHECK (cash >= 0), "realized_pnl" numeric(20,2) NOT NULL, "unrealized_pnl" numeric(20,2) NOT NULL, "current_equity" numeric(20,2) NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "tournament_entries_user_sequence_idx" ON "tournament_entries" ("tournament_id", "user_id", "sequence_number");
CREATE INDEX IF NOT EXISTS "tournament_entries_tournament_idx" ON "tournament_entries" ("tournament_id");
